INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Bahasa Thailand Terdengar Asing dan Sulit$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak orang Indonesia ingin bisa bahasa Thailand karena gemar drama, kuliner, atau berencana wisata dan bisnis ke sana. Namun bahasa Thailand memakai huruf yang sama sekali berbeda dan sistem 5 nada yang menentukan arti kata. Kesalahan nada bisa mengubah "ma" (datang) menjadi kata yang sama sekali lain. Kabar baiknya: sapaan sehari-hari sangat terbatas dan bisa dikuasai dalam hitungan hari dengan latihan rutin.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: 5 Nada dan Partikel Sopan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bahasa Thailand adalah bahasa bernada: nada rendah, sedang, tinggi, turun, dan naik. Kalimat menjadi sopan dengan menambahkan "khrap" (dibaca khrap, untuk pria) atau "kha" (untuk wanita) di akhir. Sapaan umum adalah "sawadee" (สวัสดี) yang bisa dipakai untuk halo maupun selamat tinggal. Mengucapkan nama dengan nada salah itu wajar bagi pemula, orang Thailand biasanya tetap memahami dari konteks.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$$Aplikasi belajar nada Thailand (bisa dipakai offline)$$, $$Kamus Thailand-Indonesia bergambar$$, $$Video percakapan sehari-hari dengan subtitle$$, $$Buku catatan nada per kata$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Sapaan dan Kalimat Bertahan Hidup$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$$Langkah 1: Kuasai "sawadee khrap/kha" — sapaan untuk hampir semua situasi, ucapkan dengan senyum.$$, $$Langkah 2: "Khop khun khrap/kha" (ขอบคุณ) artinya terima kasih; "khop khun maak" untuk terima kasih banyak.$$, $$Langkah 3: "Sabai dee mai?" artinya apa kabar; jawab "sabai dee" (baik-baik saja).$$, $$Langkah 4: "Tao rai?" artinya berapa harganya; "lot noi dai mai?" artinya bisa dikurangi sedikit?$$, $$Langkah 5: "Hong nam yoo tee nai?" — di mana toilet? Sangat berguna saat bepergian.$$, $$Langkah 6: "Mai pet" (ไม่เผ็ด) artinya tidak pedas; "pet nit noi" artinya sedikit pedas.$$, $$Langkah 7: "Pood Thai dai nit noi" — saya bisa bahasa Thailand sedikit; orang lokal akan sangat menghargai usaha ini.$$, $$Langkah 8: Latih nada dengan merekam suara sendiri dan membandingkan dengan audio asli; fokus pada kata-kata bernada tinggi dan turun yang paling sering salah.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$$Kesalahan nada mengubah arti — tetapi jangan takut bicara; konteks biasanya menyelamatkan.$$, $$Memakai "khrap" untuk wanita atau "kha" untuk pria terdengar janggal; hafalkan yang sesuai dengan diri sendiri.$$, $$Jangan menyentuh kepala orang Thailand dan jangan menunjuk dengan kaki — etiket tubuh sama pentingnya dengan bahasa.$$, $$Mengandalkan romanisasi (tulisan latin) tanpa mendengar bunyinya membuat nada tidak pernah benar.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Berhasil jika Anda bisa menyapa, berterima kasih, bertanya harga, dan meminta tolong dalam bahasa Thailand tanpa membaca catatan. Target lanjutan: kuasai angka 1-100 untuk tawar-menawar dan belajar huruf Thailand dasar agar bisa membaca papan nama jalan.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Dada Berdebar Tiba-tiba$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Jantung berdebar (palpitasi) adalah sensasi jantung berdetak cepat, kuat, atau tidak beraturan. Sebagian besar kasus pada orang sehat disebabkan hal sepele seperti kopi, kurang tidur, cemas, atau kelelahan. Namun pada sebagian kecil kasus, palpitasi bisa menjadi tanda gangguan irama jantung yang butuh penanganan dokter. Artikel ini membantu membedakan keduanya. Artikel ini berisi informasi umum, bukan pengganti nasihat medis; konsultasikan ke dokter untuk keluhan yang menetap.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Cara Kerja Irama Jantung$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Jantung normal berdetak 60-100 kali per menit saat istirahat. Sistem listrik alami jantung (nodus SA) mengatur irama ini. Kafein, nikotin, stres, demam, dehidrasi, dan anemia bisa membuat nodus SA bekerja lebih cepat atau memicu detak tambahan yang terasa sebagai "lompatan" di dada. Detak tambahan sesekali pada jantung yang sehat umumnya tidak berbahaya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan: Catat Pola Debaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$$Catat kapan berdebar: saat istirahat, olahraga, atau setelah kopi/teh/rokok$$, $$Hitung perkiraan denyut dengan memegang pergelangan tangan selama 15 detik x 4$$, $$Catat gejala penyerta: pusing, sesak, nyeri dada, atau pingsan$$, $$Catat obat dan suplemen yang sedang dikonsumsi$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Saat Berdebar Terjadi dan Evaluasi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$$Langkah 1: Duduk dan tenangkan diri; cemas mempercepat detak sehingga berdebar makin terasa.$$, $$Langkah 2: Hindari kafein dan rokok pada hari itu; minum air putih cukup.$$, $$Langkah 3: Lakukan napas lambat: tarik napas 4 detik, tahan 4 detik, buang 6 detik, ulangi 5 menit.$$, $$Langkah 4: Kurangi kopi menjadi maksimal 1-2 cangkir per hari dan tidur 7-9 jam.$$, $$Langkah 5: Jika berdebar muncul saat olahraga berat lalu hilang saat istirahat, catat polanya untuk dilaporkan ke dokter.$$, $$Langkah 6: Jika berdebar hilang total setelah perbaikan gaya hidup, lanjutkan kebiasaan baik tersebut.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tanda Bahaya: Wajib ke Dokter atau IGD$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$$Nyeri atau rasa tertekan di dada bersamaan dengan berdebar$$, $$Pingsan atau hampir pingsan saat berdebar$$, $$Sesak napas berat yang tidak membaik dengan istirahat$$, $$Detak sangat cepat (>150/menit) yang berlangsung lebih dari beberapa menit$$, $$Ada riwayat penyakit jantung atau kematian mendadak di keluarga$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Penutup: Kapan Tenang, Kapan Bertindak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Tenang bila debaran sesekali, jelas pemicunya (kopi, begadang, stres), dan tidak ada gejala penyerta. Bertindak bila sering, tanpa pemicu jelas, atau disertai tanda bahaya di atas. Mengabaikan palpitasi yang disertai tanda bahaya berisiko melewatkan gangguan irama seperti fibrilasi atrium yang bisa memicu stroke; sebaliknya panik berlebihan justru memicu kecemasan kronis. Pemeriksaan jantung dasar (EKG) di puskesmas atau klinik adalah langkah awal yang mudah dan murah. Informasi ini bersifat umum; keputusan medis tetap di tangan dokter yang memeriksa langsung.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Pulau Vulkanik?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Pulau vulkanik adalah daratan yang terbentuk dari tumpukan lava dan material letusan gunung berapi bawah laut yang akhirnya muncul ke permukaan. Prosesnya bisa memakan waktu ratusan ribu hingga jutaan tahun. Sebagian besar pulau vulkanik berada di zona subduksi lempeng tektonik, termasuk Cincin Api Pasifik yang mengelilingi Samudra Pasifik.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Krakatau: Anak yang Bangkit dari Laut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Letusan Krakatau 1883 adalah salah satu yang terbesar dalam sejarah tercatat; suaranya terdengar hingga ribuan kilometer. Dari kaldera yang tersisa, muncul gunung baru bernama Anak Krakatau pada 1927 yang terus tumbuh hingga kini. Letusannya pada Desember 2018 memicu tsunami Selat Sunda, pengingat bahwa pulau vulkanik aktif tetap berbahaya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Hawaii dan Santorini: Dua Wajah Pulau Api$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Kepulauan Hawaii terbentuk dari titik panas (hotspot) di tengah Lempeng Pasifik; Gunung Kilauea yang sangat aktif membuat Pulau Besar Hawaii terus membesar. Santorini di Yunani adalah sisa kaldera raksasa dari letusan sekitar 1600 SM yang menghancurkan peradaban Minoa — dinding kalderanya kini menjadi desa-desa putih ikonik yang diduga mengilhami legenda Atlantis.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Tanah Vulkanik yang Subur — dan Risikonya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Abu vulkanik yang melapuk menghasilkan tanah andosol yang sangat subur, kaya mineral — alasan lereng gunung berapi seperti di Jawa dan Bali padat penduduk dan menjadi lumbung pertanian. Namun ancaman letusan, aliran piroklastik, lahar, dan tsunami vulkanik menuntut sistem peringatan dini, peta kawasan rawan bencana, dan jalur evakuasi yang siap.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Penutup: Pulau yang Hidup$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Pulau vulkanik adalah bukti bahwa Bumi terus berubah: ia memberi tanah subur, keindahan, dan pengetahuan, sekaligus menuntut rasa hormat pada kekuatan alam. Wisata ke sana memberi pemasukan bagi warga lokal, tetapi patuhi zona aman dan arahan pemandu — keselamatan selalu di atas foto yang bagus.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Blockchain?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Blockchain adalah buku besar digital (ledger) yang disalin ke ribuan komputer di seluruh dunia. Setiap catatan transaksi dikelompokkan dalam "blok" yang dirantai secara kriptografis ke blok sebelumnya, sehingga riwayatnya hampir mustahil diubah tanpa ketahuan. Tidak ada satu pihak pun yang mengendalikannya sendirian.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Cara Kerja: Dari Transaksi ke Blok$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Ketika terjadi transaksi, ia disiarkan ke jaringan. Komputer-komputer peserta (node) memverifikasinya, lalu transaksi yang valid dikumpulkan menjadi satu blok yang ditautkan ke blok sebelumnya lewat sidik jari digital (hash). Mengubah satu data lama berarti harus mengubah semua blok sesudahnya di mayoritas komputer jaringan — praktis mustahil.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Konsensus: Sepakat Tanpa Bos$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Jaringan butuh cara menyepakati versi catatan yang benar. Bitcoin memakai proof-of-work: komputer berlomba memecahkan teka-teki matematika yang boros energi. Jaringan yang lebih baru memakai proof-of-stake: validator dipilih berdasarkan aset yang mereka pertaruhkan, jauh lebih hemat energi. Tujuannya sama: membuat kecurangan lebih mahal daripada kejujuran.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Kegunaan Nyata dan Keterbatasan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Blockchain dipakai untuk melacak rantai pasok makanan dan obat, mencatat sertifikat tanah, menerbitkan tiket anti-palsu, dan menjalankan kontrak pintar: program yang mengeksekusi perjanjian otomatis bila syarat terpenuhi. Namun ia lambat dibanding database biasa, boros energi pada model proof-of-work, dan datanya yang kekal bermasalah bila ada data salah yang terlanjur tercatat. Tidak semua masalah butuh blockchain.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Penutup: Pahami Dulu Sebelum Terjun$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Blockchain adalah inovasi penting dalam cara manusia mencatat kepercayaan, dan konsep buku besar bersama tanpa pusat akan terus dipakai dalam berbagai bentuk — dari identitas digital hingga transparansi donasi. Namun memahaminya tidak sama dengan berinvestasi di aset kripto yang sangat fluktuatif. Pelajari teknologinya, waspadai risikonya, dan gunakan akal sehat sebelum menaruh uang.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) mengidentifikasi ungkapan greeting, leave-taking, thanking, dan apologizing; (2) menggunakannya sesuai konteks formal dan informal; (3) mempraktikkannya dalam dialog sederhana.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Empat Ungkapan Wajib: Greeting, Leave-Taking, Thanking, Apologizing$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Greeting (menyapa): formal "Good morning/afternoon/evening", informal "Hi!", "Hey!", "What's up?". Jawaban: "I'm fine, thank you" atau "Pretty good". Leave-taking (berpamitan): "Goodbye", "See you later!", "Take care!" — ingat "Good night" hanya untuk berpisah di malam hari. Thanking: "Thank you", "Thanks a lot"; respons: "You're welcome", "No problem", "My pleasure". Apologizing: "I'm sorry", "I apologize", "Excuse me"; respons: "It's okay", "That's alright", "Never mind".$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Formal vs Informal: Kapan Memakai yang Mana?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$$Formal: kepada guru, orang yang lebih tua, atau orang yang baru dikenal — "Good morning, Sir."$$, $$Informal: kepada teman sebaya — "Hey, what's up?"$$, $$Di kelas bahasa Inggris, biasakan yang formal dulu agar aman di semua situasi$$, $$Perhatikan bahasa tubuh: senyum dan kontak mata membuat sapaan terdengar tulus$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Contoh Dialog Lengkap$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Rani: "Good morning, Mrs. Dewi." Mrs. Dewi: "Good morning, Rani. How are you?" Rani: "I'm fine, thank you. I'm sorry I was absent yesterday." Mrs. Dewi: "That's alright. Don't forget to copy the lesson." Rani: "Thank you, Mrs. Dewi. Goodbye!" Mrs. Dewi: "Goodbye, take care!" Dialog ini memuat keempat kategori ungkapan sekaligus.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$$1. Kamu bertemu guru pukul 08.00. Sapaan yang tepat: ...$$, $$2. Kamu berpisah dengan teman di malam hari: ...$$, $$3. Temanmu meminjamkan pensil. Kamu berkata: ...; ia menjawab: ...$$, $$4. "Good night" dipakai untuk menyapa di malam hari. (Benar/Salah)$$, $$5. Susun dialog 4-6 baris yang memuat keempat kategori ungkapan.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban dan Tips$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$$1. Good morning, Sir/Ma'am. 2. Good night / Bye, see you tomorrow. 3. Thank you — You're welcome. 4. Salah (good night untuk berpamitan). 5. Dinilai dari kelengkapan empat kategori dan kesesuaian konteks.$$, $$Tips: tempel daftar ungkapan di cermin, praktikkan satu dialog tiap pagi, dan tantang teman role-play 2 menit. Ungkapan sosial dikuasai lewat kebiasaan, bukan hafalan semalam.$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) menyebutkan peristiwa perjuangan mempertahankan kemerdekaan; (2) menjelaskan pertempuran-pertempuran penting; (3) meneladani semangat juang para pahlawan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Mengapa Harus Berjuang Lagi?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Setelah Proklamasi 17 Agustus 1945, Belanda ingin kembali berkuasa dengan membonceng tentara Sekutu (NICA). Rakyat Indonesia menolak. Maka terjadilah perjuangan fisik (pertempuran) dan perjuangan diplomasi (perundingan) selama sekitar 4 tahun hingga Belanda mengakui kedaulatan Indonesia pada 27 Desember 1949.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Pertempuran-Pertempuran Penting$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Surabaya 10 November 1945: dipicu insiden Hotel Yamato dan ultimatum Inggris yang ditolak rakyat; Bung Tomo membakar semangat lewat radio. Hari ini diperingati sebagai Hari Pahlawan. Ambarawa (Des 1945): pasukan TKR di bawah Kolonel Sudirman memukul mundur Sekutu. Bandung Lautan Api (24 Maret 1946): rakyat membakar Bandung selatan agar tidak dikuasai musuh. Serangan Umum 1 Maret 1949: dipimpin Letkol Soeharto atas perintah Sudirman dan Sri Sultan Hamengkubuwono IX, membuktikan kepada dunia bahwa Indonesia masih berdaulat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Perjuangan Diplomasi dan Tokoh Pejuang$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$$Linggarjati (1946): Belanda mengakui RI atas Jawa, Madura, Sumatra$$, $$Renville (1948), Roem-Roijen (1949), hingga KMB di Den Haag (1949) yang mengakhiri pengakuan kedaulatan$$, $$Ir. Soekarno & Drs. Mohammad Hatta: proklamator dan pemimpin diplomasi$$, $$Jenderal Sudirman: panglima besar yang bergerilya dalam keadaan sakit$$, $$Bung Tomo: orator arek-arek Suroboyo; Sri Sultan Hamengkubuwono IX: penopang perjuangan dari Yogyakarta$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$$1. Pertempuran 10 November 1945 terjadi di kota ...$$, $$2. Pemimpin pertempuran Ambarawa adalah ...$$, $$3. Serangan Umum 1 Maret 1949 bertujuan menunjukkan kepada dunia bahwa ...$$, $$4. Jelaskan dengan bahasamu sendiri mengapa rakyat harus berjuang lagi setelah merdeka (minimal 5 kalimat).$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban dan Teladan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$$1. Surabaya. 2. Kolonel Sudirman. 3. Indonesia masih ada dan berdaulat / TNI masih kuat. 4. Dinilai dari kelogisan, penyebutan satu pertempuran dan satu perundingan.$$, $$Teladan: para pahlawan berjuang tanpa pamrih. Cara kita meneladani mereka: belajar sungguh-sungguh, jujur, disiplin, dan berkarya nyata untuk tanah air.$$]));
